-- Amber Network favorites: the people the user hand-picks as real relationships.
-- NOTE: this file is INCOMPLETE on its own. `tags` and `position` were added
-- later as lazy ALTERs inside favorites-store.js and never backported here, so a
-- database built from this file alone lacks two columns the app requires.
-- 20260826_fix_contact_favorites_columns.sql adds them. Do not edit this file --
-- it has already been applied everywhere.

CREATE TABLE IF NOT EXISTS contact_favorites (
  id          bigserial PRIMARY KEY,
  owner_id    text NOT NULL,
  contact_id  text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  UNIQUE (owner_id, contact_id)
);

CREATE INDEX IF NOT EXISTS idx_contact_favorites_owner ON contact_favorites(owner_id);
